userDefinedLinkHintCss:
/* Generated by theme-ssot — do not edit by hand */
:root {
  --vimium-accent: #ffb688;
  --vimium-accent-fg: #1a1008;
  --vimium-secondary: #e5bfa9;
  --vimium-tertiary: #cac993;
  --vimium-outline: #c4a882;
  --vimium-text: #ebe1d4;
  --vimium-muted: #d1c5b4;
  --vimium-surface2: #574451;
  --vimium-surface1: #342931;
  --vimium-surface0: #292126;
  --vimium-base: #181316;
  --vimium-mantle: #1d181c;

  --vimium-foreground-text-color: #ebe1d4;
  --vimium-background-text-color: #ebe1d4;
  --vimium-foreground-color: #1d181c;
}

/* Hints: hardcoded hex (no var()) so defaults cannot win if :root fails */
div > .vimiumHintMarker,
div.vimiumHintMarker,
div.internal-vimium-hint-marker {
  background: #ffb688 !important;
  background-image: none !important;
  border: 1px solid #1d181c !important;
  box-shadow: none !important;
  padding: 3px 4px !important;
}

div > .vimiumHintMarker span,
div.vimiumHintMarker span,
div.internal-vimium-hint-marker span {
  color: #1a1008 !important;
  font-weight: bold !important;
  font-size: 12px !important;
  text-shadow: none !important;
}

div > .vimiumHintMarker > .matchingCharacter,
div.vimiumHintMarker > .matchingCharacter,
div.internal-vimium-hint-marker > .matchingCharacter {
  color: #574451 !important;
}

/* vomnibar */
#vomnibar {
  background: #181316 !important;
  border: 2px solid #c4a882 !important;
}

#vomnibar input,
#vomnibar #vomnibar-search-area,
#vomnibar ul {
  color: #ebe1d4 !important;
  background: #181316 !important;
  border: none !important;
  box-shadow: none !important;
}

#vomnibar li {
  border-bottom: 1px solid #292126 !important;
}

#vomnibar li .source {
  color: #cac993 !important;
}

#vomnibar li em,
#vomnibar li .title,
#vomnibar li .title .match,
#vomnibar li .match {
  color: #ffb688 !important;
  font-weight: bold !important;
}

#vomnibar li .url {
  color: #e5bfa9 !important;
}

#vomnibar li.selected {
  background-color: #292126 !important;
}

/* hud */
div#hud-container {
  background: #181316 !important;
  border: 1px solid #ebe1d4 !important;
  box-shadow: none !important;
}

div#hud-container span#hud-find-input,
div#hud-container div#hud {
  color: #ebe1d4 !important;
}

div#hud-container .hud-find,
div#hud-container #search-area {
  background-color: #181316 !important;
}

::selection {
  background-color: #cac993 !important;
  color: #1a1008 !important;
}
